import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';
import './App.css';
import { useModelCache } from './useModelCache'; // Ensure the custom hook is in a separate file for clarity

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const { loadModel } = useModelCache();
  const groupRef = useRef(null);

  useEffect(() => {
    loadModel(modelPath)
      .then(setModel)
      .catch((error) => console.error('Error loading OBJ:', error));
  }, [modelPath, loadModel]);

  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [models, setModels] = useState([]);
  const [selectedModel, setSelectedModel] = useState(null);
  const [highlightedModel, setHighlightedModel] = useState(null);
  const [asciiArt, setAsciiArt] = useState('');
  const [asciiIndex, setAsciiIndex] = useState(0);
  const [asciiComplete, setAsciiComplete] = useState(false);
  const { loadModel } = useModelCache();
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 800);

  useEffect(() => {
    fetch('./models.json')
      .then((response) => response.json())
      .then((data) => {
        setModels(data);
        setSelectedModel(data[0]?.file);
        data.forEach((model) => {
          loadModel(`./stls/${model.file}`);
        });
      });
  }, []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 800);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleModelChange = (event) => {
    setSelectedModel(event.target.value);
  };

  const asciiArtString = `
......................................................................................................
..............@@@@......................@@@....................@@@@...................................
.............@@..@@...................@@@@@@@.................@@@@@@@..........@@@@@@@@@@@@@@@@@@@@...
...........(ASCII ART CONTINUES)...
  `;

  useEffect(() => {
    if (asciiIndex < asciiArtString.length) {
      const interval = setInterval(() => {
        setAsciiArt((prev) => prev + asciiArtString[asciiIndex]);
        setAsciiIndex((prev) => prev + 1);
      }, 5);

      return () => clearInterval(interval);
    } else {
      setAsciiComplete(true);
    }
  }, [asciiIndex, asciiArtString]);

  return (
    <div className="container">
      {isMobile ? (
        <div className="dropdown-container">
          <select value={selectedModel} onChange={handleModelChange}>
            {models.map((model) => (
              <option key={model.file} value={model.file}>
                {model.name}
              </option>
            ))}
          </select>
        </div>
      ) : (
        <div className="sidebar">
          <h3>Select a Project</h3>
          <ul>
            {models.map((model) => (
              <li
                key={model.file}
                className={`${selectedModel === model.file ? 'selected' : ''} ${highlightedModel === model.file ? 'highlighted' : ''}`}
                onClick={() => setSelectedModel(model.file)}
                onMouseEnter={() => setHighlightedModel(model.file)}
                onMouseLeave={() => setHighlightedModel(null)}
              >
                {selectedModel === model.file ? `> ${model.name}` : model.name}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="right-container">
        {!asciiComplete && <div className="ascii-art">{asciiArt}</div>}

        {asciiComplete && (
          <Canvas
            style={{ backgroundColor: 'black' }}
            camera={{ position: [2.5, 2.5, 2.5], fov: 45 }}
          >
            <ambientLight intensity={0.5} />
            <spotLight position={[10, 10, 10]} intensity={1} />
            <directionalLight position={[5, 5, 5]} intensity={1} />
            {selectedModel && <ModelLoader modelPath={`./stls/${selectedModel}`} />}
            <OrbitControls enableZoom={false} />
          </Canvas>
        )}
      </div>
    </div>
  );
};

export default App;
